import{_ as t,a,o,a6 as l}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Locales","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/locales/index.md","filePath":"api/rest-api/shop/locales/index.md","lastUpdated":1787725411000}'),n={name:"api/rest-api/shop/locales/index.md"};function s(r,e,d,i,c,h){return o(),a("div",null,e[0]||(e[0]=[l('<h1 id="locales" tabindex="-1">Locales <a class="header-anchor" href="#locales" aria-label="Permalink to &quot;Locales&quot;">​</a></h1><p>The Locales menu lists the languages the storefront is published in. A locale carries its language code, display name, text direction (<code>ltr</code> / <code>rtl</code>) and an optional logo. Use it to build a language switcher, to know which <code>locale</code> codes you may pass on catalog and content requests, and to render right-to-left layouts correctly.</p><h2 id="when-a-client-uses-this" tabindex="-1">When a Client Uses This <a class="header-anchor" href="#when-a-client-uses-this" aria-label="Permalink to &quot;When a Client Uses This&quot;">​</a></h2><p>Call the list once on app start to populate a language picker. The <code>code</code> you read here is the value you send as the <code>X-Locale</code> header (or the <code>locale</code> query parameter) on every localised request — catalog, categories, CMS pages, attributes.</p><h2 id="what-a-locale-row-carries" tabindex="-1">What a Locale Row Carries <a class="header-anchor" href="#what-a-locale-row-carries" aria-label="Permalink to &quot;What a Locale Row Carries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Why it matters</th></tr></thead><tbody><tr><td><code>code</code></td><td>The value <code>X-Locale</code> expects. The numeric <code>id</code> is not accepted as a locale.</td></tr><tr><td><code>name</code></td><td>Display label for a language switcher.</td></tr><tr><td><code>direction</code></td><td><code>ltr</code> or <code>rtl</code>. This exists so a client can flip its layout without hardcoding a list of right-to-left languages.</td></tr><tr><td><code>logoPath</code> / <code>logoUrl</code></td><td>Optional flag or badge image, <code>null</code> when the store set none.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td><code>null</code> on locales installed with the store — normal, not an error.</td></tr></tbody></table><h2 id="locale-resolution-on-other-endpoints" tabindex="-1">Locale Resolution on Other Endpoints <a class="header-anchor" href="#locale-resolution-on-other-endpoints" aria-label="Permalink to &quot;Locale Resolution on Other Endpoints&quot;">​</a></h2><p>Sending an unknown or disabled <code>X-Locale</code> is not an error: the request falls back to the channel&#39;s default locale and returns content in that language instead. Content endpoints report which locale actually answered — a CMS page&#39;s <code>translation.locale</code>, a category&#39;s <code>translation.locale</code> — so read that back rather than assuming the requested code was honoured.</p><p>Locales are configured per channel, so the set enabled on one storefront may differ from another. This endpoint lists every locale the store has, not just the ones the current channel enables; the channel&#39;s own set is on its <a href="/api/rest-api/shop/channels/get-channels.html">channel</a> record.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/locales/get-locales.html">Get All Locales</a></td><td><code>GET /api/shop/locales</code></td><td>Paginated list of every available locale.</td></tr><tr><td><a href="/api/rest-api/shop/locales/get-single-locale.html">Get Single Locale</a></td><td><code>GET /api/shop/locales/{id}</code></td><td>A single locale by id.</td></tr></tbody></table><p>The list is static reference data — cache it and refresh only when the store adds a language.</p><p>All Locale endpoints are public reads that require only the storefront key — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',13)]))}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
